13	
14	/* Every database operation goes through a bounded probe_* function. The login inherits only
15	   those functions from `probe`, with no table grants or BYPASSRLS. The reducer stays here,
16	   between the lock and commit functions in one transaction. A steady pass updates nothing;
17	   windows flush in one array call, never a row per check or a row to schedule one.
18	
19	   Heartbeats take the same path with their own lock and commit (migration 019): `judgeHeartbeat`
20	   locks the row, asks `heartbeat.ts` for the next event in what the receiver recorded, steps the
21	   same reducer, and commits the state, its effects and the row's cursor together.
22	
23	   An SSL check's certificate (expiry and issuer) rides the same commit as a `cert` effect, only
24	   when it differs from what the locked row holds for its host (migration 020), so a steady pass
25	   still writes nothing. The leader's domain lookups have their own two functions
26	   (`loadDomains`, `recordDomain`). */
27	
28	export type Monitor = {
29	  id: string;
30	  workspaceId: string;
31	  name: string;
32	  type: CheckedType;
33	  target: string;
34	  intervalSec: number;
35	  config: Record<string, unknown>;
36	  paused: boolean;
37	  /** Builder monitors may be checked from `fra1` and prefer it to confirm. The plan is the one the
38	      workspace's members last showed with a verified session (`probe_builder_workspaces`), since a
39	      probe has no session to ask Clerk with. */
40	  builder: boolean;
41	  /** The secret headers an HTTP check sends, opened. Null when one wouldn't open (the probe's
42	      `CREDENTIALS_KEY` isn't the dashboard's): the monitor isn't checked rather than checked
43	      without its credentials, which would fail it as a 401 from every location. */
44	  headers: Record<string, string> | null;
45	  /** The row's `updated_at` in microseconds. Every dashboard edit, pause and resume moves it, and
46	      the probe never writes it, so it names the version of the monitor a check ran against. */
47	  version: string;
48	  /** No outcome counted for this version yet: new, or just edited. Its home checks it once within
49	      seconds instead of waiting for its turn, which for an SSL monitor can be hours away. */
50	  unchecked?: boolean;
51	};
52	
53	export type ProbeRow = ProbeInfo & { url: string };
54	
55	/** A heartbeat as a home schedules it: its settings, version and what has arrived, without the
56	    payloads, which are read under the lock when an event is judged. */
57	export type HeartbeatMonitor = {
58	  id: string;
59	  workspaceId: string;
60	  config: HeartbeatConfig;
61	  version: string;
62	  paused: boolean;
63	  row: HeartbeatRow;
64	};
65	
66	/** What one judgement did: `written` with the runs to count, or `unchanged` (nothing due) with
67	    the next deadline, or `paused` (paused, deleted, or no longer a heartbeat). */
68	export type HeartbeatJudged = { applied: "written" | "unchanged" | "paused"; runs: { at: number; ok: boolean }[]; due: number | null };
69	
70	const ms = (v: unknown): number | null => (v === null || v === undefined ? null : Number(v));
71	const iso = (t: number | null) => (t === null ? null : new Date(t).toISOString());
72	
73	function pingOf(at: unknown, payload: unknown, note: unknown): Ping | null {
74	  const t = ms(at);
75	  if (t === null) return null;
76	  const p = payload && typeof payload === "object" && !Array.isArray(payload) ? (payload as Record<string, unknown>) : {};
77	  return { at: t, payload: p, note: typeof note === "string" ? note : null };
78	}
79	
80	/** A row of `probe_load_heartbeats` or `probe_lock_heartbeat` as `heartbeat.ts` reads it. */
81	function heartbeatRowOf(r: Record<string, unknown>): HeartbeatRow {
82	  return {
83	    state: (r.state as State | null) ?? null,
84	    versionAt: Number(r.version_at),
85	    config: configOf((r.config as Record<string, unknown>) ?? {}),
86	    ping: pingOf(r.ping_at, r.ping_payload, r.ping_note),
87	    start: pingOf(r.start_at, r.start_payload, r.start_note),
88	    fail: pingOf(r.fail_at, r.fail_payload, r.fail_note),
89	    finishes: Number(r.finishes ?? 0),
90	    judgedAt: ms(r.judged_at),
91	    judgedFinishes: Number(r.judged_finishes ?? 0),
92	    runAt: ms(r.run_at),
93	  };
94	}
95	
96	/** What the incident screen reads from `evidence` (`src/lib/workspace.ts`). */
97	function evidenceJson(m: Pick<Monitor, "type" | "target" | "config">, e: Evidence) {
98	  const c = m.config;
99	  const request =
100	    m.type === "http"
101	      ? `${String(c.method ?? "GET")} ${m.target}`
102	      : m.type === "tcp"
103	        ? `TCP ${String(c.host ?? m.target)}:${String(c.port ?? "")}`
104	        : m.type === "ssl"
105	          ? `TLS ${String(c.host ?? m.target)}:443`
106	          : m.type === "stripe" ? "Stripe account webhook deliveries"
107	            : m.type === "supabase" ? `Supabase project ${m.target}`
108	              : `${String(c.record ?? "")} ${String(c.name ?? m.target)}`;
109	  return {
110	    request,
111	    summary: e.failure?.message ?? "",
112	    ...(e.status !== undefined ? { status: e.status } : {}),
113	    ...(e.assertion ? { assertion: `${e.assertion.path} ${e.assertion.op} ${e.assertion.expected}`.trim(), got: e.assertion.got ?? "" } : {}),
114	    locations: e.locations,
115	    snippet: e.snippet ?? "",
116	  };
117	}
118	
119	/** `unchanged` includes a steady pass: even its ordering marker needs no write. */
120	export type Applied = "written" | "unchanged" | "paused" | "moved" | "duplicate";
121	
122	/** The certificate an SSL outcome read, from whichever of its checks reached one (the second
123	    look, when the first broke off before a handshake): expiry in epoch seconds, and issuer. */
124	export function certOf(outcome: Report["outcome"]): { expiresAt: string; expiresAtSec: number; issuer: string | null } | null {
125	  for (const r of [outcome.confirm, outcome.first]) {
126	    const d = r?.detail;
127	    const t = typeof d?.expiresAt === "string" ? Date.parse(d.expiresAt) : NaN;
128	    if (!Number.isFinite(t)) continue;
129	    const issuer = typeof d?.issuer === "string" && d.issuer.trim() ? d.issuer.trim().slice(0, 200) : null;
130	    return { expiresAt: new Date(t).toISOString(), expiresAtSec: Math.floor(t / 1000), issuer };
131	  }
132	  return null;
133	}
134	
135	const place = (loc: string) => (isLocationId(loc) ? locations[loc].city : loc);
136	
137	export class Store {
138	  /** `credentialsKey` opens the secret headers the dashboard sealed (`src/lib/seal.ts`).
139	      `workspaces`, when given, is the only workspaces whose monitors this probe checks: the
140	      development probes check the owner's, never the rows the test suites create and delete in
141	      the same project (`docs/environments.md`, Probes). Production passes none. */
142	  constructor(
143	    readonly pool: pg.Pool,
144	    private credentialsKey?: Buffer,
145	    private workspaces?: readonly string[],
146	    private probeId?: string,
147	  ) {}
148	
149	  static connect(url: string, credentialsKey?: Buffer, workspaces?: readonly string[], probeId?: string): Store {
150	    return new Store(new pg.Pool({ connectionString: url, max: 4, idleTimeoutMillis: 30_000 }), credentialsKey, workspaces, probeId);
151	  }
152	
153	  private openHeaders(monitorId: string, sealed: { name: string; sealed: string }[]): Record<string, string> | null {
154	    const headers: Record<string, string> = {};
155	    for (const s of sealed) {
156	      if (!this.credentialsKey) return null;
157	      try {
158	        headers[s.name] = open(s.sealed, headerContext(monitorId, s.name), this.credentialsKey);
159	      } catch {
160	        return null;
161	      }
162	    }
163	    return headers;
164	  }
165	
166	  close(): Promise<void> {
167	    return this.pool.end();
168	  }
169	
170	  async heartbeat(p: ProbeRow): Promise<void> {
171	    await this.pool.query(
172	      "select public.probe_heartbeat($1, $2, $3, $4)",
173	      [p.id, p.location, p.builderOnly, p.url],
174	    );
175	  }
176	
177	  async leave(id: string): Promise<void> {
178	    await this.pool.query("select public.probe_leave($1)", [id]);
179	  }
180	
181	  async liveProbes(): Promise<ProbeRow[]> {
182	    const { rows } = await this.pool.query("select * from public.probe_live()");
183	    return rows.map((r) => ({ id: r.id, location: r.location, builderOnly: r.builder_only, url: r.url }));
184	  }
185	
186	  async loadMonitors(): Promise<Monitor[]> {
187	    const [ordinary, services, builders] = await Promise.all([
188	      this.pool.query("select * from public.probe_load_monitors($1::text[])", [this.workspaces ?? null]),
189	      this.pool.query("select * from public.probe_load_service_monitors($1::text[])", [this.workspaces ?? null]),
190	      this.builderWorkspaces(),
191	    ]);
192	    const rows = [...ordinary.rows, ...services.rows];
193	    return rows.map((r) => ({
194	      id: r.id,
195	      workspaceId: r.workspace_id,
196	      name: r.name,
197	      type: r.type,
198	      target: r.target,
199	      intervalSec: r.interval_sec,
200	      config: r.config,
201	      paused: r.paused,
202	      builder: builders.has(r.workspace_id),
203	      headers: this.openHeaders(r.id, r.secrets),
204	      version: r.version,
205	      unchecked: r.unchecked,
206	    }));
207	  }
208	
209	  /** The Builder workspaces among the ones this probe checks. A database without the function yet
210	      (a probe deployed before its migration) answers none, which is every monitor as Free: how it
211	      was before the plan reached the probe. */
212	  private async builderWorkspaces(): Promise<Set<string>> {
213	    try {
214	      const { rows } = await this.pool.query("select workspace_id from public.probe_builder_workspaces($1::text[])", [this.workspaces ?? null]);
215	      return new Set(rows.map((r) => r.workspace_id as string));
216	    } catch (error) {
217	      if ((error as { code?: string }).code === "42883") return new Set();
218	      throw error;
219	    }
220	  }
221	
222	  async loadHeartbeats(): Promise<HeartbeatMonitor[]> {
223	    const { rows } = await this.pool.query("select * from public.probe_load_heartbeats($1::text[])", [this.workspaces ?? null]);
224	    return rows.map((r) => {
225	      const row = heartbeatRowOf(r);
226	      return { id: r.id, workspaceId: r.workspace_id, config: row.config, version: r.version, paused: r.paused, row };
227	    });
228	  }
229	
230	  /** Judge one heartbeat's next due event under its lock (`heartbeat.ts`), at the database's
231	      clock. One event per transaction: a run judged missed and the late ping that recovers it
232	      are two transitions, and the commit function takes one. The caller repeats until nothing is
233	      due. Another home that judged first moves the cursor, and the commit refuses this one. */
234	  async judgeHeartbeat(monitorId: string, location: string): Promise<HeartbeatJudged> {
235	    const c = await this.pool.connect();
236	    try {
237	      await c.query("begin");
238	      const { rows } = await c.query("select * from public.probe_lock_heartbeat($1)", [monitorId]);
239	      const r = rows[0];
240	      if (!r || r.paused) {
241	        await c.query("rollback");
242	        return { applied: "paused", runs: [], due: null };
243	      }
244	      const row = heartbeatRowOf(r);
245	      const { event, due } = plan(row, Number(r.db_now));
246	      if (!event) {
247	        await c.query("rollback");
248	        return { applied: "unchanged", runs: [], due };
249	      }
250	      const judged = judge(row, event, location);
251	      const before: MonitorState = fresh(row.state);
252	      const { next, effects } = step("heartbeat", before, { first: judged.outcome });
253	      const writes = effects.map((e) => {
254	        if (e.kind === "transition") return { kind: e.kind, from: e.from, to: e.to };
255	        if (e.kind === "open_incident") return { kind: e.kind, evidence: judged.evidence, timeline: [{ t: iso(event.at), text: judged.opened }] };
256	        const f: Located = e.result;
257	        return { kind: e.kind, location: f.location, failureKind: f.failure?.kind ?? "missed", message: (f.failure?.message ?? "").slice(0, 500),
258	          ms: Math.round(f.ms), snippet: f.snippet ?? null, detail: null };
259	      });
260	      const k = judged.cursor;
261	      await c.query(
262	        "select public.probe_commit_heartbeat($1, $2, $3, $4, $5, $6, $7, $8, $9::jsonb)",
263	        [monitorId, r.version, iso(row.judgedAt), iso(event.at), iso(k.judgedAt), k.judgedFinishes, iso(k.runAt),
264	          next.state, JSON.stringify(writes)],
265	      );
266	      await c.query("commit");
267	      return { applied: "written", runs: judged.runs, due: null };
268	    } catch (err) {
269	      await c.query("rollback").catch(() => {});
270	      throw err;
271	    } finally {
272	      c.release();
273	    }
274	  }
275	
276	  /** One statement per window, including the merge and the daily-tier triggers. */
277	  async flushRollups(rows: RollupRow[]): Promise<void> {
278	    // Stores used for a one-off test without a probe identity retain the original API. Only a
279	    // running registered probe may refresh a dead-man receipt, including on an empty flush.
280	    if (rows.length === 0 && !this.probeId) return;
281	    const rounded = (v: number | null) => v === null ? null : Math.round(v);
282	    await this.pool.query(
283	      this.probeId
284	        ? "select public.probe_flush_with_receipt($9, $1::text[], $2::text[], $3::timestamptz[], $4::int[], $5::int[], $6::int[], $7::int[], $8::int[])"
285	        : "select public.probe_flush_rollups($1::text[], $2::text[], $3::timestamptz[], $4::int[], $5::int[], $6::int[], $7::int[], $8::int[])",
286	      [rows.map((r) => r.monitorId), rows.map((r) => r.location),
287	        rows.map((r) => new Date(r.windowStart * 1000).toISOString()), rows.map((r) => r.checks), rows.map((r) => r.failures),
288	        rows.map((r) => rounded(r.p50Ms)), rows.map((r) => rounded(r.p95Ms)), rows.map((r) => rounded(r.maxMs)),
289	        ...(this.probeId ? [this.probeId] : [])],
290	    );
291	  }
292	
293	  /** Read, order, step and write under one monitor lock. The report carries only the version
294	      that was checked; all configuration used for the decision and evidence comes from the row.
295	
296	      `probe_outcome_at` is the newest outcome that changed counters or produced effects. Thus
297	      it includes every counted failure, even while already down. Older reports cannot undo newer
298	      counting. Locations at that second deduplicate resends across homes and restarts; distinct
299	      locations in the same second retain arrival order (the accepted clock-skew limitation).
300	
301	      A no-op needs no marker: replaying it before anything changes is still a no-op; after a
302	      change, the newer marker or state_since fences it out. No row is updated for a steady pass. */
303	  async apply(report: Report): Promise<Applied> {
304	    const { monitorId, version, outcome, atSec } = report;
305	    const at = new Date(atSec * 1000).toISOString();
306	    const c = await this.pool.connect();
307	    try {
308	      await c.query("begin");
309	      const { rows } = await c.query(
310	        "select * from public.probe_lock_monitor($1)",
311	        [monitorId],
312	      );
313	      const row = rows[0];
314	      if (!row || row.paused) {
315	        await c.query("rollback");
316	        return "paused";
317	      }
318	      if (row.version !== version || (row.since !== null && atSec < row.since)) {
319	        await c.query("rollback");
320	        return "moved";
321	      }
322	      if (row.outcome_at !== null && atSec < row.outcome_at) {
323	        await c.query("rollback");
324	        return "moved";
325	      }
326	      const sameSecond = row.outcome_at === atSec;
327	      if (sameSecond && row.probe_outcome_locations.includes(outcome.first.location)) {
328	        await c.query("rollback");
329	        return "duplicate";
330	      }
331	      const before: MonitorState = {
332	        state: row.state, slowStreak: row.probe_slow_streak,
333	        passStreak: row.probe_pass_streak, failStreak: row.probe_fail_streak,
334	      };
335	      const runtime = (row.config.__runtime ?? {}) as StripeRuntime & { pausedOrDeleted?: boolean };
336	      let nextRuntime = runtime;
337	      let judged = outcome;
338	      const observations: StripeObservation[] = [];
339	      if (row.type === "stripe") {
340	        const judge = (r: Located): Located => {
341	          const observation = r.detail?.observation as StripeObservation | undefined;
342	          if (!observation) return r;
343	          observations.push(observation);
344	          const result = judgeStripe(row.config as StripeConfig, observation, runtime, before.state === "down");
345	          return { ...result, ms: r.ms, location: r.location };
346	        };
347	        judged = { first: judge(outcome.first), ...(outcome.confirm ? { confirm: judge(outcome.confirm) } : {}) };
348	      }
349	      if (row.type === "supabase") {
350	        nextRuntime = {
351	          pausedOrDeleted: outcome.first.failure?.kind === "project_paused" && outcome.confirm?.failure?.kind === "project_paused" };
352	      }
353	      const { next, effects } = step(row.type, before, judged);
354	      if (observations.length) {
355	        const outstanding = new Set(observations.flatMap(o => o.events.map(e => e.id)));
356	        const handled = new Set((runtime.seen ?? []).filter(id => outstanding.has(id)));
357	        // Only terminal failures in a counted, confirmed outcome have been handled.
358	        // In-flight and out-of-window events did not count; consuming them would hide
359	        // a later terminal failure. Neither recovery passes nor one-location noise
360	        // can add new ids, even while the existing incident is down.
361	        if (next.state === "down" && !judged.first.ok && judged.confirm && !judged.confirm.ok) {
362	          for (const observation of observations) {
363	            for (const event of affectedStripeEvents(row.config as StripeConfig, observation)) {
364	              if (event.pending === 0) handled.add(event.id);
365	            }
366	          }
367	        }
368	        nextRuntime = handled.size ? { seen: [...handled].sort() } : {};
369	      }
370	      const runtimeChanged = JSON.stringify(runtime) !== JSON.stringify(nextRuntime);
371	      const changed = next.state !== before.state || next.slowStreak !== before.slowStreak ||
372	        next.passStreak !== before.passStreak || next.failStreak !== before.failStreak;
373	      // A database without migration 020 returns no certificate columns, and its commit takes no
374	      // certificate: none is sent, so an SSL outcome there is written exactly as before.
375	      const read = row.type === "ssl" && "cert_expires_at" in row ? certOf(outcome) : null;
376	      const cert = read && (row.cert_host !== row.target_host || row.cert_expires_at === null ||
377	        Math.floor(row.cert_expires_at) !== read.expiresAtSec || (row.cert_issuer ?? null) !== read.issuer) ? read : null;
378	      if (!changed && effects.length === 0 && !cert && !runtimeChanged) {
379	        await c.query("commit");
380	        return "unchanged";
381	      }
382	      const m = { id: row.id, workspaceId: row.workspace_id, name: row.name, type: row.type, target: row.target, config: row.config };
383	      const writes: Record<string, unknown>[] = effects.map((e) => {
384	        if (e.kind === "transition") {
385	          return { ...e, at };
386	        } else if (e.kind === "open_incident") {
387	          const [first, second] = e.evidence.locations;
388	          const timeline = [
389	            { t: at, text: `Check failed in ${place(first)}` },
390	            { t: at, text: second ? `Confirmed from ${place(second)}, incident opened` : "Incident opened" },
391	          ];
392	          return { kind: e.kind, evidence: evidenceJson(m, e.evidence), timeline };
393	        } else {
394	          const r: Located = e.result;
395	          return { kind: e.kind, location: r.location, failureKind: r.failure?.kind ?? "connect",
396	            message: (r.failure?.message ?? "").slice(0, 500), status: r.status ?? null,
397	            ms: r.ms, snippet: r.snippet ?? null, detail: r.detail ?? null };
398	        }
399	      });
400	      if (cert) writes.push({ kind: "cert", expiresAt: cert.expiresAt, issuer: cert.issuer });
401	      if (runtimeChanged) writes.push({ kind: "service_runtime", runtime: nextRuntime });
402	      await c.query(
403	        "select public.probe_commit_monitor($1, $2, $3, $4, $5, $6, $7, $8, $9::jsonb)",
404	        [monitorId, version, at, next.state, next.slowStreak, next.passStreak, next.failStreak,
405	          sameSecond ? [...row.probe_outcome_locations, outcome.first.location] : [outcome.first.location], JSON.stringify(writes)],
406	      );
407	      await c.query("commit");
408	      return "written";
409	    } catch (err) {
410	      await c.query("rollback").catch(() => {});
411	      throw err;
412	    } finally {
413	      c.release();
414	    }
415	  }
416	
417	  /** Each host's registration row, the longest of its names that has one (migration 020). */
418	  async loadDomains(hosts: string[]): Promise<DomainRow[]> {
419	    const { rows } = await this.pool.query("select * from public.probe_load_domains($1::text[])", [hosts]);
420	    return rows.map((r) => ({ host: r.host, name: r.name, status: r.status, error: r.error ?? null, attemptedAt: Math.round(Number(r.attempted_at) * 1000) }));
421	  }
422	
423	  /** One lookup's answer for `host`, under the name it is about. False when no SSL monitor names
424	      the host any more, and nothing was written. */
425	  async recordDomain(host: string, r: DomainResult): Promise<boolean> {
426	    const found = r.status === "found" ? r : null;
427	    const { rows } = await this.pool.query(
428	      "select public.probe_record_domain($1, $2, $3, $4, $5, $6) as recorded",
429	      [host, r.domain, r.status, found?.expiresAt != null ? new Date(found.expiresAt).toISOString() : null,
430	        found?.registrar ?? null, r.status === "failed" ? r.error.slice(0, 200) : null],
431	    );
432	    return rows[0]?.recorded === true;
433	  }
434	}
