118	         extract(epoch from m.probe_outcome_at)::float8, m.probe_outcome_locations,
119	         m.target_host, m.cert_host, extract(epoch from m.cert_expires_at)::float8, m.cert_issuer
120	  from public.monitors m where m.id = p_id and m.type in ('http', 'tcp', 'ssl', 'dns', 'stripe', 'supabase') for update;
121	$fn$;
122	
123	create or replace function public.probe_commit_monitor(
124	  p_id text, p_version text, p_at timestamptz, p_state text,
125	  p_slow integer, p_pass integer, p_fail integer, p_locations text[], p_effects jsonb
126	)
127	returns void language plpgsql security definer set search_path = '' as $fn$
128	declare
129	  m public.monitors%rowtype;
130	  e jsonb;
131	  v_expires timestamptz;
132	begin
133	  select * into m from public.monitors where id = p_id for update;
134	  if not found then raise exception 'probe_monitor_missing' using errcode = '22023'; end if;
135	  if p_version is distinct from (extract(epoch from m.updated_at) * 1000000)::bigint::text then
136	    raise exception 'probe_monitor_moved' using errcode = '22023';
137	  end if;
138	  if m.type not in ('http', 'tcp', 'ssl', 'dns', 'stripe', 'supabase') or
139	     (m.paused_at is not null and (m.paused_until is null or m.paused_until > pg_catalog.now())) then
140	    raise exception 'probe_monitor_not_checkable' using errcode = '22023';
141	  end if;
142	  if (p_state is not null and p_state not in ('up', 'degraded', 'down')) or
143	     (p_state is null and m.state is not null) then
144	    raise exception 'probe_state_invalid' using errcode = '22023';
145	  end if;
146	  if p_effects is null or pg_catalog.jsonb_typeof(p_effects) <> 'array' or
147	     pg_catalog.jsonb_array_length(p_effects) > 6 then
148	    raise exception 'probe_effects_invalid' using errcode = '22023';
149	  end if;
150	
151	  update public.monitors set state = p_state,
152	    state_since = case when state is distinct from p_state then p_at else state_since end,
153	    probe_slow_streak = p_slow, probe_pass_streak = p_pass, probe_fail_streak = p_fail,
154	    probe_outcome_at = p_at, probe_outcome_locations = p_locations where id = p_id;
155	
156	  for e in select value from pg_catalog.jsonb_array_elements(p_effects) loop
157	    case e->>'kind'
158	      when 'transition' then
159	        if (e->>'from') is distinct from m.state or (e->>'to') is distinct from p_state or p_state is null then
160	          raise exception 'probe_transition_invalid' using errcode = '22023';
161	        end if;
162	        insert into public.transitions (monitor_id, from_state, to_state, at)
163	        values (p_id, e->>'from', e->>'to', p_at);
164	        if e->>'from' = 'down' then
165	          update public.incidents set resolved_at = greatest(p_at, opened_at),
166	            timeline = timeline || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
167	              't', e->>'at', 'text', 'Two checks passed, incident closed'))
168	          where monitor_id = p_id and resolved_at is null;
169	        end if;
170	      when 'open_incident' then
171	        if p_state is distinct from 'down' then
172	          raise exception 'probe_incident_invalid' using errcode = '22023';
173	        end if;
174	        -- As 017 (reviews 34 and 35): an incident still open here describes something else, so it
175	        -- is closed and this outage gets its own row. Opening time is capped at the database
176	        -- clock (skew protection).
177	        update public.incidents set resolved_at = greatest(least(p_at, pg_catalog.now()), opened_at),
178	          timeline = timeline || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
179	            't', pg_catalog.now(), 'text', 'A new outage opened its own incident, this one closed'))
180	        where monitor_id = p_id and resolved_at is null;
181	        insert into public.incidents (workspace_id, monitor_id, title, severity, opened_at, evidence, timeline)
182	        values (m.workspace_id, p_id, pg_catalog.left(m.name || ' is down', 200), 'down',
183	                least(p_at, pg_catalog.now()), e->'evidence', e->'timeline');
184	      when 'record_failure' then
185	        insert into public.check_failures (monitor_id, location, at, kind, message, status, ms, snippet, detail)
186	        values (p_id, e->>'location', p_at, e->>'failureKind', e->>'message',
187	                (e->>'status')::integer, (e->>'ms')::integer, e->>'snippet', nullif(e->'detail', 'null'::jsonb));
188	        delete from public.check_failures where monitor_id = p_id and id not in
189	          (select id from public.check_failures where monitor_id = p_id order by at desc, id desc limit 20);
190	      when 'cert' then
191	        -- An SSL monitor's alone, with an expiry a certificate can carry (above); otherwise
192	        -- skipped, never the outcome's failure.
193	        begin
194	          v_expires := (e->>'expiresAt')::timestamptz;
195	        exception when others then
196	          v_expires := null;
197	        end;
198	        if m.type = 'ssl' and m.target_host is not null and v_expires is not null and
199	           v_expires >= timestamptz '1950-01-01 00:00:00+00' and v_expires < timestamptz '10000-01-01 00:00:00+00' then
200	          update public.monitors set cert_host = m.target_host, cert_expires_at = v_expires,
201	            cert_issuer = case when pg_catalog.jsonb_typeof(e->'issuer') = 'string'
202	                               then pg_catalog.left(nullif(pg_catalog.btrim(e->>'issuer'), ''), 200) end
203	          where id = p_id;
204	        end if;
205	      when 'service_runtime' then
206	        if m.type not in ('stripe','supabase') or jsonb_typeof(e->'runtime') is distinct from 'object'
207	          or octet_length((e->'runtime')::text) > 250000
208	          or (e->'runtime') - array['seen','pausedOrDeleted'] <> '{}'::jsonb then
209	          raise exception 'probe_service_runtime_invalid' using errcode = '22023';
210	        end if;
211	        update public.monitors set service_runtime = (e->'runtime') || jsonb_build_object('version', p_version) where id = p_id;
212	      else raise exception 'probe_effect_invalid' using errcode = '22023';
213	    end case;
214	  end loop;
215	end;
216	$fn$;
217	
218	revoke all on function public.probe_load_service_monitors(text[]) from public, anon, authenticated, service_role;
219	grant execute on function public.probe_load_service_monitors(text[]) to probe;
220	-- CREATE OR REPLACE retains the existing lock/commit ACLs.
221	create or replace trigger monitors_forget_open_windows
222	after update of updated_at on public.monitors
223	for each row when (new.type in ('http','tcp','ssl','dns','stripe','supabase') and old.updated_at is distinct from new.updated_at)
224	execute function public.forget_open_windows_on_edit();
225	
226	-- Add only the safe service label to 024's snapshot; internal cursors never leave the server.
227	create or replace function public.workspace_snapshot(p_workspace_id text)

