# The probe's systemd unit, as Staygreen's own provisioning writes it.
# Install as /etc/systemd/system/staygreen-probe.service (root-owned, mode 644).
# It runs the bundle from `npm run probe:build` (probe/dist/main.js), copied to
# /opt/staygreen-probe/main.js, as the unprivileged `staygreen` user that setup.sh creates.
# Its variables come from /etc/staygreen-probe.env (see probe.env.example), root-owned with
# mode 600: systemd reads it as root, and the service user can't open it.
[Unit]
Description=Staygreen probe
After=network-online.target
Wants=network-online.target
[Service]
User=staygreen
Group=staygreen
WorkingDirectory=/opt/staygreen-probe
EnvironmentFile=/etc/staygreen-probe.env
ExecStart=/usr/bin/node /opt/staygreen-probe/main.js
Restart=on-failure
RestartSec=5
# A planned stop drains: the probe finishes and writes its own checks before leaving the fleet.
TimeoutStopSec=90
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
RestrictSUIDSGID=true
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6
CapabilityBoundingSet=
UMask=0077
StateDirectory=staygreen-probe
[Install]
WantedBy=multi-user.target
# The probe watchdog Worker (watchdog/worker.ts): every minute it reads when each expected probe
# last delivered its numbers, and messages an operator Telegram chat when one has been silent
# for ten minutes, every 30 minutes while it stays silent, and when it recovers. It has no
# public route: every HTTP request answers 404. Copy this file to watchdog/wrangler.toml and
# replace the name and the Hyperdrive id. No secret lives here: see the end.
name = "monitoring-watchdog"
main = "worker.ts"
compatibility_date = "2026-04-01"
# `pg` reaches Postgres through Workers' TCP sockets, which it finds through Node's APIs.
compatibility_flags = ["nodejs_compat"]
workers_dev = false
preview_urls = false

[triggers]
crons = ["* * * * *"]

# The watchdog's own Hyperdrive configuration, with caching off, whose origin is a login that
# is a member of `watchdog` and nothing else: it can call public.watchdog_flush_status only.
#   wrangler hyperdrive create <name>-db --connection-string="postgres://<login>:<password>@db.<project-ref>.supabase.co:5432/postgres" --caching-disabled true
[[hyperdrive]]
binding = "HYPERDRIVE"
id = "<hyperdrive-id>"

# One SQLite-backed Durable Object, the exported Watchdog class, runs the checks one at a time
# and keeps the alert receipts, so a silent probe isn't reported again every minute.
[[durable_objects.bindings]]
name = "WATCHDOG"
class_name = "Watchdog"

